#!/usr/bin/env python3
"""Bind source library IDs to cached QC cells and freeze a small technical subset."""
from check_AIDA_repeats import *
import numpy as np,anndata as ad,datetime,hashlib
def main():
 pre=json.loads((P/'outputs/round3/AIDA_source_metadata_preflight.json').read_text());local=P/'work/round3/AIDA_metadata_segments'/f"{pre['dataset_id']}.METADATA_ONLY.sparse.h5ad";receipt=json.loads((O/'P4_AIDA_additional_metadata_receipt.json').read_text());fs=fsspec.filesystem('https',client_kwargs={'trust_env':True,'timeout':aiohttp.ClientTimeout(total=180)})
 reader=MetadataRangeReader(local,pre['url'],fs,receipt,O/'P4_AIDA_cell_link_receipt.json')
 with reader,h5py.File(reader,'r') as h:d=pd.DataFrame({k:col(h['obs'][k]) for k in ['donor_id','sample_id','library_id','suspension_uuid','observation_joinid']})
 assert not d.observation_joinid.duplicated().any();d=d.rename(columns={'donor_id':'source_donor'});d.to_parquet(P/'work/round5/AIDA_cell_library_link.parquet',index=False)
 obs=[]
 man=json.loads((P/'outputs/round3/R2_AIDA_evaluation_raw_manifest.json').read_text());assert man['complete']
 for r in man['chunks']:
  a=ad.read_h5ad(P/r['path'],backed='r');obs.append(a.obs[['donor','observation_joinid','celltype','age','soma_joinid']].reset_index(drop=True));a.file.close()
 obs=pd.concat(obs,ignore_index=True).merge(d,on='observation_joinid',how='left',validate='one_to_one');assert obs.library_id.notna().all() and obs.donor.eq(obs.source_donor).all();obs.to_parquet(P/'work/round5/AIDA_QC_cell_library_link.parquet',index=False)
 n=obs.groupby(['donor','library_id','celltype']).size().unstack('celltype',fill_value=0);cts=['B','CD4T','CD8T','MONO','NK'];alllibs=obs.groupby('donor').library_id.nunique();ok=n[cts].ge(30).all(axis=1);eligible=n[ok].reset_index().groupby('donor').library_id.nunique();eligible=sorted(set(eligible[eligible.eq(2)].index)&set(alllibs[alllibs.eq(2)].index));assert len(eligible)>=20
 # Select on cell counts / metadata only, before any split-library clock prediction.
 selected=sorted(np.random.default_rng(np.random.SeedSequence([20261025,5401])).choice(eligible,20,replace=False).tolist());q=obs[obs.donor.isin(selected)].copy();library_order=q[['donor','library_id']].drop_duplicates().sort_values(['donor','library_id']);library_order['replicate']=library_order.groupby('donor').cumcount()+1;q=q.merge(library_order,on=['donor','library_id'],validate='many_to_one');q['gsm']=q.donor+'|technical'+q.replicate.astype(str);q.to_parquet(P/'work/round5/P4_selected_cells.parquet',index=False);n.reset_index().to_csv(O/'P4_AIDA_library_cell_QC.csv',index=False);q.groupby(['donor','age','sample_id','suspension_uuid','library_id','replicate','gsm','celltype']).size().reset_index(name='n_cells').to_csv(O/'P4_selected_technical_pairs.csv',index=False)
 contract={'seed':20261025,'substream':[20261025,5401],'recorded_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source':'AIDA Phase1 Freezev2; exact prior Census dataset/version','n_eligible_donors_two_GEX_libraries_and_all_five_types_ge30_cells':len(eligible),'n_selected_donors':20,'selected_donors':selected,'age_min':float(q.age.min()),'age_max':float(q.age.max()),'n_cells':len(q),'selection':'seeded uniform20 from eligible metadata/QC donors; library order lexicographic UUID per donor; no prediction/outcome used','repeat_type':'same blood-draw technical replicate GEX libraries; independent GEM channels of same suspension/pool, usually same sequencing lane; interval0days','run_scope':'one dataset,20donors,2models,fivecelltypes,raw and nestedLODO ageacceleration;2000paired donor bootstrap, refitLODO per draw; no training','published_point':'A1 reliability convention continuous mean of100native15cell pseudocell predictions; log1pCP10K full raw library denominator; exact linear identity permitted','e_point':'frozen R4 model on pooled raw counts per donor×library×type,log2(1+CPM) with full library denominator','count_coverage':'Require all nonzero e features and source-measured published features; do not fill genes absent only from local4044cache','biological_longitudinal_validation':False,'not_a_new_age_accuracy_test_set':'AIDA was used for prior external accuracy, never training/model selection; only library split/reliability is new','status':'FROZEN_BEFORE_SPLIT_LIBRARY_PREDICTIONS'};(O/'P4_external_selection_contract.json').write_text(json.dumps(contract,indent=2));ledger=json.loads((P/'outputs/gate_ledger.json').read_text());ledger['round5']['P4_external_selection']=contract;(P/'outputs/gate_ledger.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2));print(json.dumps(contract,indent=2),flush=True)
if __name__=='__main__':main()
